import sys;sys.path.insert(0,'..')
from gcommon import *
SRC=srcs([GD('gittutorial','Git – gittutorial (A Tutorial Introduction to Git)'),GD('git-config','Git – git-config'),GD('git-init'),GD('giteveryday','Git – giteveryday (Everyday Git)'),('https://www.odoo.com/documentation/20.0/contributing/development/git_guidelines.html','Odoo 20 – Git guidelines'),('https://www.odoo.com/documentation/20.0/administration/on_premise/source.html','Odoo 20 – Source install')])
def dia(vi):
    t=('Ba vùng làm việc của Git và remote' if vi else 'Git\'s three areas and the remote','Sơ đồ do Vinc Academy biên soạn.' if vi else 'Diagram by Vinc Academy.','dg-%s-g01'%('vi' if vi else 'en'))
    items=[(4,(['Thư mục','làm việc'],['Working','tree']),('file bạn đang sửa','the files you edit'),False),(170,(['Staging','(index)'],['Staging','(index)']),('thứ sẽ commit','what you commit'),True),(336,(['Repo cục bộ'],['Local repo']),('lịch sử trong .git','history in .git'),False),(502,(['Remote'],['Remote']),('GitLab của nhóm','your team\'s GitLab'),False)]
    b=''
    for x,ti,su,ac in items:
        b+='<rect class="%s" x="%d" y="45" width="134" height="80" rx="12" />\n'%('dg-accent' if ac else 'dg-box',x)
        for i,l in enumerate(ti[0 if vi else 1]): b+='<text class="dg-title" x="%d" y="%d">%s</text>\n'%(x+14,68+i*18,l)
        b+='<text class="dg-text" x="%d" y="115">%s</text>\n'%(x+14,su[0 if vi else 1])
    for x,l in [(138,'git add'),(304,'git commit'),(470,'git push')]:
        b+='<path class="dg-arrow" d="M%d 85 h22 m-8 -6 l8 6 l-8 6" /><text class="dg-text" text-anchor="middle" x="%d" y="34">%s</text>\n'%(x,x+14,l)
    b+='<text class="dg-text" x="4" y="150">%s</text>\n'%('Chiều ngược lại: git restore làm mới thư mục làm việc; git fetch/pull mang commit từ remote về.' if vi else 'The other way: git restore refreshes the working tree; git fetch/pull bring commits from the remote.')
    return fig('640 162',t[0],b,t[1],t[2])
def build(vi):
    t=lambda a,b:a if vi else b
    sb=SB('a01',ident=False)
    c1=sb.P('git --version','git config --global user.name "Nguyễn Văn An"','git config --global user.email "an.nguyen@example.com"','git config --global init.defaultBranch main','git config --global core.editor "code --wait"','git config --global --list --show-origin')
    c2=sb.P('mkdir vinc_course','cd vinc_course','git init','git status','ls -A','cat .git/HEAD')
    c3=sb.P('echo "# vinc_course" > README.md','git status -s','git add README.md','git status -s','git commit -m "Thêm README cho vinc_course"','git log --oneline','git status')
    c4=sb.P('git config --global alias.st "status -sb"','git st','git config --get user.name','git config --show-origin user.email')
    e=SB('a01e',ident=False);e.q('git config --global user.useConfigOnly true');e.q('git init -q vinc_course');e.cd('vinc_course');e.w('README.md','# vinc_course\n')
    e.q('git add README.md');err=e.T('git commit -m "Thêm README"').replace('$ git commit -m "Thêm README"\n','')
    err=pre(err).replace('<pre><code>','<pre><code>$ git commit -m "Thêm README"\n',1)
    o=summ((t('Tóm tắt nhanh','In short'),t('<strong>Git là công cụ lưu lịch sử thay đổi của mã nguồn ngay trên máy bạn, còn GitLab hay GitHub là nơi cả nhóm chia sẻ và review.</strong> Bài này đưa bạn từ máy trống đến commit đầu tiên của repo <code>vinc_course</code>: cài Git, khai báo tên và email, tạo repo bằng <code>git init</code>, hiểu ba vùng (thư mục làm việc, staging, repo) và biết tự tra cứu bằng <code>git help</code>. Mọi lệnh trong bài đều đã chạy thật trên Git 2.47.','<strong>Git records the history of your source code on your own machine; GitLab and GitHub are where a whole team shares and reviews it.</strong> This part takes you from an empty machine to the first commit of the <code>vinc_course</code> repository: installing Git, setting your name and email, creating a repo with <code>git init</code>, understanding the three areas (working tree, staging, repository) and looking things up with <code>git help</code>. Every command here was really run on Git 2.47.')))
    o+=h2('git-la-gi',t('Git là gì và vì sao nhóm nào cũng dùng','What Git is and why every team uses it'))
    o+=p(t('Hãy hình dung module <code>vinc_course</code> của bạn đang có 20 file Python và XML. Hôm nay bạn sửa model, mai sửa view, tuần sau đồng nghiệp thêm báo cáo. Nếu chỉ dùng thư mục thường, bạn sẽ có những thứ như <code>vinc_course_final</code>, <code>vinc_course_final_2</code> hay <code>vinc_course_dung_that</code>, và khi lỗi xuất hiện thì không ai biết ai đã đổi dòng nào. Git giải quyết đúng chỗ đó: nó chụp lại trạng thái của cả dự án mỗi khi bạn <em>commit</em>, kèm tên người sửa, thời điểm và lời nhắn giải thích.','Picture your <code>vinc_course</code> module with twenty Python and XML files. Today you change a model, tomorrow a view, next week a colleague adds a report. With plain folders you end up with <code>vinc_course_final</code>, <code>vinc_course_final_2</code> and <code>vinc_course_really_final</code>, and when a bug appears nobody knows who changed which line. Git solves exactly that: each time you <em>commit</em> it snapshots the whole project together with the author, the time and a message that explains the change.'))
    o+=p(t('Git là hệ thống quản lý phiên bản <strong>phân tán</strong>: mỗi máy giữ một bản sao đầy đủ của lịch sử, nên bạn xem log, so sánh hay tạo nhánh ngay cả khi không có mạng. Mạng chỉ cần khi bạn muốn đồng bộ với đồng nghiệp. Trong doanh nghiệp, điều này đi kèm một quy trình quen thuộc: mỗi người làm trên nhánh riêng, đẩy lên GitLab, mở merge request để đồng nghiệp xem lại rồi mới gộp vào nhánh chính. Cả quy trình đó sẽ được mở dần qua 12 bài của series; bài này đặt nền móng.','Git is a <strong>distributed</strong> version control system: every machine keeps a full copy of the history, so you can read the log, compare changes or create branches even offline. You only need the network to sync with colleagues. In a company this comes with a familiar routine: everyone works on their own branch, pushes it to GitLab, opens a merge request for review, and only then merges into the main branch. The 12 parts of this series unfold that whole routine; this one lays the foundation.'))
    o+=tbl([t('Tên','Name'),t('Là gì','What it is'),t('Bạn dùng để','You use it to')],[
        ['<strong>Git</strong>',t('Chương trình dòng lệnh cài trên máy bạn','A command-line program installed on your machine'),t('Commit, tạo nhánh, xem lịch sử, gộp thay đổi','Commit, branch, read history, merge changes')],
        ['<strong>GitLab</strong>',t('Dịch vụ lưu repo của nhóm, có merge request, phân quyền và CI','A hosting service for team repositories with merge requests, permissions and CI'),t('Chia sẻ code, review, tự động kiểm tra','Share code, review it, run automatic checks')],
        ['<strong>GitHub</strong>',t('Dịch vụ tương tự GitLab (gọi là pull request)','A service similar to GitLab (it calls them pull requests)'),t('Cùng mục đích; lệnh Git phía bạn giống hệt','Same purpose; the Git commands on your side are identical')]])
    o+=p(t('Điểm cần nhớ: <strong>Git không phụ thuộc GitLab</strong>. Bạn có thể dùng Git hoàn toàn trên máy, rồi sau này mới nối với GitLab hay GitHub. Series dùng GitLab vì nhiều doanh nghiệp tự dựng GitLab nội bộ cho code của khách hàng; mọi lệnh Git đều dùng được nguyên vẹn với GitHub.','Remember that <strong>Git does not depend on GitLab</strong>. You can use Git entirely on your machine and connect it to GitLab or GitHub later. This series uses GitLab because many companies run an internal GitLab for client code; every Git command works unchanged with GitHub.'))
    o+=h2('cai-dat',t('Cài đặt Git','Installing Git'))
    o+=p(t('Cài một lần, dùng mãi. Theo trang tải về chính thức của Git, mỗi hệ điều hành có một cách quen thuộc:','Install it once and use it forever. Following Git\'s official download page, each operating system has a familiar route:'))
    o+=tbl([t('Hệ điều hành','System'),t('Cách cài','How to install')],[['Windows',t('Tải <em>Git for Windows</em> từ git-scm.com, giữ các tùy chọn mặc định, dùng Git Bash hoặc terminal của VS Code','Download <em>Git for Windows</em> from git-scm.com, keep the default options, then use Git Bash or the VS Code terminal')],['Ubuntu / Debian','<code>sudo apt install git</code>'],['macOS',t('<code>brew install git</code>, hoặc chạy <code>git</code> lần đầu để hệ thống mời cài Xcode Command Line Tools','<code>brew install git</code>, or run <code>git</code> once and let the system offer the Xcode Command Line Tools')]])
    o+=p(t('Sau khi cài, mở terminal và chạy <code>git --version</code>. Series này kiểm thử trên Git 2.47; các lệnh hiện đại như <code>git switch</code> và <code>git restore</code> có từ bản 2.23, nên bất kỳ bản 2.30 trở lên đều đủ dùng.','After installing, open a terminal and run <code>git --version</code>. This series was tested on Git 2.47; the modern commands <code>git switch</code> and <code>git restore</code> arrived in 2.23, so any version from 2.30 up is fine.'))
    o+=h2('cau-hinh',t('Cấu hình lần đầu: tên, email, nhánh mặc định','First-time setup: name, email, default branch'))
    o+=p(t('Mỗi commit ghi lại tác giả, nên việc đầu tiên là nói cho Git biết bạn là ai. Hãy dùng đúng email bạn đăng ký trên GitLab để commit được gắn vào tài khoản của bạn. Ba cài đặt khác cũng nên đặt ngay: nhánh mặc định của repo mới (<code>main</code>), và trình soạn thảo mà Git mở khi cần bạn gõ lời nhắn dài.','Every commit records its author, so the first job is to tell Git who you are. Use the same email you registered on GitLab so your commits are linked to your account. Two other settings are worth doing now: the default branch of new repos (<code>main</code>) and the editor Git opens when it needs a longer message.'))
    o+=c1
    o+=p(t('Cờ <code>--global</code> lưu vào file <code>.gitconfig</code> trong thư mục home của bạn (kết quả trên cho thấy nguồn nhờ <code>--show-origin</code>). Git còn hai tầng nữa, tầng sau ghi đè tầng trước:','The <code>--global</code> flag stores the value in the <code>.gitconfig</code> file in your home folder (the output above shows the source thanks to <code>--show-origin</code>). Git has two more levels, and the later one overrides the earlier:'))
    o+=tbl([t('Tầng','Level'),t('Cờ','Flag'),t('Lưu ở','Stored in'),t('Phạm vi','Applies to')],[
        ['system','<code>--system</code>',t('File cấu hình của hệ thống','The system config file'),t('Mọi người dùng trên máy','Every user on the machine')],
        ['global','<code>--global</code>','<code>~/.gitconfig</code>',t('Mọi repo của bạn','All your repos')],
        ['local',t('<code>--local</code> (mặc định)','<code>--local</code> (default)'),'<code>.git/config</code>',t('Chỉ repo hiện tại','Only the current repo')]])
    o+=p(t('Tầng <em>local</em> rất hữu ích khi bạn dùng một máy cho cả dự án công ty lẫn dự án cá nhân: đặt email công ty ở global, rồi trong repo cá nhân chạy <code>git config user.email "ban@example.com"</code> (không cờ) để chỉ repo đó dùng email khác. ','The <em>local</em> level is handy when one laptop serves both company and personal projects: keep the company email globally, then in a personal repo run <code>git config user.email "you@example.com"</code> (no flag) so only that repo uses another address. '))
    o+=h2('ba-vung',t('Ba vùng làm việc: hiểu một lần dùng cả đời','Three areas: understand them once, use them forever'))
    o+=dia(vi)
    o+=p(t('Hầu hết nhầm lẫn của người mới đều đến từ việc không phân biệt ba nơi mà file có thể nằm:','Most beginner confusion comes from not telling apart the three places a file can live:'))
    o+=ul([t('<strong>Thư mục làm việc</strong> là các file bạn thấy và sửa hằng ngày.','The <strong>working tree</strong> is the files you see and edit every day.'),t('<strong>Staging</strong> (còn gọi là <em>index</em>) là “giỏ hàng” chứa những thay đổi bạn đã chọn cho lần commit kế tiếp, nhờ <code>git add</code>.','The <strong>staging area</strong> (also called the <em>index</em>) is a shopping basket of the changes you picked for the next commit with <code>git add</code>.'),t('<strong>Repo cục bộ</strong> là lịch sử commit, nằm trong thư mục ẩn <code>.git</code>. Xóa <code>.git</code> là mất toàn bộ lịch sử, nên đừng nghịch thư mục này.','The <strong>local repository</strong> is the commit history, stored in the hidden <code>.git</code> folder. Delete <code>.git</code> and the whole history is gone, so do not tinker inside it.')])
    o+=p(t('Tách staging khỏi commit nghe thừa, nhưng đó là lợi thế lớn: bạn có thể sửa năm file mà chỉ commit hai file liên quan, giữ mỗi commit làm đúng một việc. Vùng thứ tư, <strong>remote</strong>, chỉ xuất hiện khi bạn nối repo với GitLab ở bài 4.','Separating staging from committing sounds redundant, yet it is a big advantage: you can edit five files and commit only the two that belong together, keeping each commit about one thing. The fourth place, the <strong>remote</strong>, appears when you connect the repo to GitLab in part 4.'))
    o+=h2('repo-dau-tien',t('Tạo repo đầu tiên cho vinc_course','Creating the first repo for vinc_course'))
    o+=p(t('<code>git init</code> biến một thư mục thành repo bằng cách tạo thư mục <code>.git</code> bên trong. <code>git status</code> là lệnh bạn sẽ gõ nhiều nhất: nó luôn cho biết bạn đang ở nhánh nào và cái gì đang chờ xử lý.','<code>git init</code> turns a folder into a repo by creating a <code>.git</code> folder inside. <code>git status</code> is the command you will type most: it always tells you which branch you are on and what is waiting for attention.'))
    o+=c2
    o+=p(t('Tệp <code>.git/HEAD</code> cho biết nhánh hiện tại là <code>main</code>, đúng như ta đã đặt ở <code>init.defaultBranch</code>. Giờ thử vòng đời nhỏ nhất: tạo file, đưa vào staging, commit.','The <code>.git/HEAD</code> file says the current branch is <code>main</code>, just as we set in <code>init.defaultBranch</code>. Now the smallest possible life cycle: create a file, stage it, commit it.'))
    o+=c3
    o+=p(t('Hãy đọc kỹ hai lần <code>git status -s</code>: dấu <code>??</code> nghĩa là file chưa được theo dõi, còn <code>A</code> ở cột đầu nghĩa là file đã nằm trong staging. Mã băm như <code>'+c3.split('[main (root-commit) ')[1][:7]+'</code> là định danh ngắn của commit; trên máy bạn nó sẽ khác vì phụ thuộc thời gian và tác giả.','Read the two <code>git status -s</code> outputs closely: <code>??</code> means the file is untracked, and <code>A</code> in the first column means it is already in staging. A value such as <code>'+c3.split('[main (root-commit) ')[1][:7]+'</code> is the short identifier of the commit; on your machine it will differ because it depends on time and author.'))
    o+=h2('tro-giup',t('Tự tra cứu khi quên lệnh','Looking things up when you forget'))
    o+=p(t('Không ai nhớ hết tùy chọn của Git, kể cả người dùng lâu năm. Có hai thói quen cứu bạn: <code>git help &lt;lệnh&gt;</code> (hoặc <code>git &lt;lệnh&gt; --help</code>) mở trang hướng dẫn đầy đủ, còn <code>git &lt;lệnh&gt; -h</code> in nhanh cú pháp ngay trong terminal. Gõ sai tên lệnh, Git còn gợi ý lệnh gần giống bằng thông báo <em>“is not a git command”</em>.','Nobody remembers every Git option, veterans included. Two habits save you: <code>git help &lt;command&gt;</code> (or <code>git &lt;command&gt; --help</code>) opens the full manual page, while <code>git &lt;command&gt; -h</code> prints the usage right in the terminal. If you mistype a command, Git suggests similar ones with an <em>“is not a git command”</em> message.'))
    o+=p(t('Muốn gõ ít hơn, bạn đặt <em>alias</em> cho lệnh hay dùng. Ví dụ dưới đây biến <code>git st</code> thành bản rút gọn của <code>git status</code>, rồi dùng <code>git config --get</code> và <code>--show-origin</code> để biết một giá trị đang lấy từ đâu:','To type less, set an <em>alias</em> for commands you use often. The example below makes <code>git st</code> a short form of <code>git status</code>, then uses <code>git config --get</code> and <code>--show-origin</code> to see where a value comes from:'))
    o+=c4
    o+=h2('trong-odoo',t('Bạn gặp Git ở đâu khi làm Odoo','Where you meet Git in Odoo work'))
    o+=tbl([t('Tình huống','Situation'),t('Ví dụ','Example')],[
        [t('Lấy mã nguồn Odoo','Getting the Odoo source'),'<code>git clone --branch 20.0 --single-branch https://github.com/odoo/odoo.git</code>'],
        [t('Quản lý module riêng','Managing your own module'),t('Repo <code>vinc_course</code> chứa thư mục module, thêm vào <code>--addons-path</code>','A <code>vinc_course</code> repo holding the module folder, added to <code>--addons-path</code>')],
        [t('Chuẩn commit của Odoo','Odoo\'s commit standard'),t('Tài liệu Odoo yêu cầu đặt <code>user.email</code> và <code>user.name</code> trước khi commit, và có quy ước tiêu đề <code>[TAG] module: mô tả</code> (xem bài 10)','Odoo\'s guidelines ask you to define <code>user.email</code> and <code>user.name</code> before committing, and a <code>[TAG] module: description</code> title convention (see part 10)')],
        [t('Tách môi trường','Separating environments'),t('Nhánh riêng cho từng khách hàng hay phiên bản Odoo','Branches per customer or per Odoo version')]])
    o+=call(t('Lỗi hay gặp khi mới học','Common beginner mistakes'),[
        t('<strong>Commit bằng danh tính sai.</strong> Nếu chưa cấu hình, nhiều máy vẫn commit được vì Git tự đoán tên và email từ tài khoản máy, nhưng sẽ in cảnh báo <em>“Your name and email address were configured automatically based on your username and hostname. Please check that they are accurate.”</em> Đừng bỏ qua dòng này. Cách sửa commit vừa tạo là <code>git commit --amend --reset-author</code> sau khi đã đặt đúng <code>user.name</code> và <code>user.email</code>.','<strong>Committing with the wrong identity.</strong> If you have not configured it, many machines still commit because Git guesses a name and email from the system account, but it prints <em>“Your name and email address were configured automatically based on your username and hostname. Please check that they are accurate.”</em> Do not ignore that line. To fix the commit you just made, run <code>git commit --amend --reset-author</code> after setting the right <code>user.name</code> and <code>user.email</code>.'),
        t('<strong>Gặp “Author identity unknown”.</strong> Khi Git không đoán được (hoặc bạn bật <code>user.useConfigOnly</code> để cấm đoán), commit bị từ chối với thông báo dưới đây. Chỉ cần chạy hai lệnh <code>git config</code> mà nó gợi ý.','<strong>Seeing “Author identity unknown”.</strong> When Git cannot guess (or you turned on <code>user.useConfigOnly</code> to forbid guessing), the commit is refused with the message below. Simply run the two <code>git config</code> commands it suggests.')+'</li>\n</ul>\n'+err+'<ul>\n<li>'+t('<strong>Tạo repo trong repo.</strong> Chạy <code>git init</code> bên trong một thư mục đã nằm trong repo khác sẽ tạo repo lồng nhau và làm <code>git status</code> khó hiểu. Hãy kiểm tra bằng <code>git status</code> trước khi <code>init</code>.','<strong>A repo inside a repo.</strong> Running <code>git init</code> inside a folder that already belongs to another repo creates a nested repo and makes <code>git status</code> confusing. Check with <code>git status</code> before you <code>init</code>.')])
    o+=h2('tong-ket',t('Tổng kết','Summary'))
    o+=ul([t('Git lưu lịch sử ngay trên máy bạn; GitLab/GitHub chỉ là nơi chia sẻ và review.','Git keeps history on your own machine; GitLab and GitHub are only where you share and review.'),t('Cấu hình một lần: <code>user.name</code>, <code>user.email</code>, <code>init.defaultBranch</code>; tầng local ghi đè global.','Configure once: <code>user.name</code>, <code>user.email</code>, <code>init.defaultBranch</code>; local overrides global.'),t('Ba vùng: thư mục làm việc → staging (<code>git add</code>) → repo (<code>git commit</code>); thêm remote khi đẩy lên GitLab.','Three areas: working tree → staging (<code>git add</code>) → repository (<code>git commit</code>); add the remote when you push to GitLab.'),t('<code>git status</code> luôn cho bạn biết bước tiếp theo; <code>git help</code> và <code>-h</code> giúp tự tra cứu.','<code>git status</code> always tells you the next step; <code>git help</code> and <code>-h</code> let you look things up yourself.')])
    o+=p(t('Bạn đã có repo và commit đầu tiên. Bài tiếp theo đi vào vòng lặp hằng ngày: sửa file, xem khác biệt bằng <code>git diff</code>, chọn thứ cần commit, đọc <code>git log</code> và loại những file không bao giờ nên vào repo bằng <code>.gitignore</code>.','You now have a repo and a first commit. The next part covers the daily loop: edit files, see differences with <code>git diff</code>, pick what to commit, read <code>git log</code> and keep files that should never enter the repo out with <code>.gitignore</code>.'))
    o+=cta(vi,CTA)
    o+='\n'+I+'<h2 id="faq">'+t('Câu hỏi thường gặp','Frequently asked questions')+'</h2>\n'+I+'{FAQ}\n'
    o+='\n'+I+'<h2 id="nguon">'+t('Nguồn tham khảo','References')+'</h2>\n'+SRC
    return o
write('.',build(True),build(False))
